def binary_to_decimal(binary):
    """
    Convert a binary number (given as a string or integer digits)
    to its decimal equivalent.

    Example:
        binary_to_decimal("1010") -> 10
    """
    if isinstance(binary, int):
        binary = str(binary)
    else:
        binary = str(binary).strip()

    if not binary:
        raise ValueError("Binary number must not be empty")

    decimal_value = 0

    for digit in binary:
        if digit not in "01":
            raise ValueError("Binary number must contain only 0 and 1")
        decimal_value = decimal_value * 2 + int(digit)

    return decimal_value


# Example usage
