def sort_mixed_list(mixed_list, numbers_first=True):
    """
    Sort a mixed list containing integers and strings.

    Parameters:
    - mixed_list: list of integers and strings
    - numbers_first: if True, integers appear before strings;
                   if False, strings appear before integers

    Returns:
    - A new sorted list
    """
    def sort_key(item):
        if isinstance(item, int):
            # Integers are grouped first when numbers_first=True
            return (0 if numbers_first else 1, item)
        elif isinstance(item, str):
            # Strings are grouped second when numbers_first=True
            return (1 if numbers_first else 0, item)
        else:
            raise TypeError("This function only supports integers and strings.")

    return sorted(mixed_list, key=sort_key)


# Example usage
