print(sort_mixed_list(mixed_list))
# Output: [2, 5, 10, 'apple', 'banana', 'cherry']

# If you want strings first:
print(sort_mixed_list(mixed_list, numbers_first=False))
# Output: ['apple', 'banana', 'cherry', 2, 5, 10]
```

